local config = {
  ui_story_31860101_1_dialog_content = "Tentu saja! Apa itu?",
  ui_story_31860101_2_dialog_content = "Tadi aku bermimpi.",
  ui_story_31860101_3_dialog_content = "Itu hanya hari kerja biasa, tetapi saya merasa sangat mengantuk sehingga saya tertidur di sore hari.",
  ui_story_31860101_4_dialog_content = "Itu sudah larut malam ketika aku bangun. Semua rekan saya telah meninggalkan kantor.",
  ui_story_31860101_5_dialog_content = "Apakah Anda sering begadang di kantor?",
  ui_story_31860101_6_dialog_content = "Ya. Berkat sifat khusus saya, terkadang saya harus bekerja lembur hingga larut malam, hanya untuk mengejar ketinggalan.",
  ui_story_31860101_7_dialog_content = "Untungnya, pada hari itu tidak ada hal mendesak yang perlu diurus.",
  ui_story_31860101_8_dialog_content = "Bagaimanapun, PlayerName, kamu tahu apa...?",
  ui_story_31860101_9_dialog_content = "A-Apa?",
  ui_story_31860101_10_dialog_content = "<size=50>Matthieu menakutkan ketika dia marah!</size>",
  ui_story_31860101_11_dialog_content = "Saya bermimpi dia menegur saya karena tidak bekerja cukup keras dan ceroboh dalam kasus saya saat ini.",
  ui_story_31860101_12_dialog_content = "Boo-hoo... Dia mengatakan bahwa saya selalu menggunakan narkolepsi sebagai alasan, yang menunda kemajuan orang lain.",
  ui_story_31860101_13_dialog_content = "Saya tidak bisa menangani kasus lain selama sebulan, dan saya harus membersihkan Balai Kehakiman selama sebulan sebagai hukuman saya...",
  ui_story_31860101_14_dialog_content = "Matthieu bahkan mengatakan bahwa dia akan mengambil kursi malas saya!",
  ui_story_31860101_15_dialog_content = "Hehe, saya kira itu adalah mimpi Matthieu, Kanan?",
