  ui_story_31860101_17_dialog_content = "Apapun itu, itu hanya mimpi. Tapi mengapa Matthieu menegurmu?",
  ui_story_31860101_18_dialog_content = "Ya, saya bermimpi ada kasus yang sedang saya kerjakan.",
