  ui_story_31860101_20_dialog_content = "Itu menghilang sebelum saya menyadarinya, tetapi saya masih mendapat kesedihan Matthieu.",
  ui_story_31860101_21_dialog_content = "Mimpi yang aneh...",
  ui_story_31860101_22_dialog_content = "Tapi saya pikir saya bisa mengerti mengapa Matthieu marah dalam mimpimu.",
