  ui_story_31860101_24_dialog_content = "Meskipun itu adalah mimpi, saya masih merasa ada sesuatu yang tidak beres ketika saya bangun.",
  ui_story_31860101_25_dialog_content = "Apa pendapatmu tentang mimpi, PlayerName?",
  ui_story_31860101_26_option_content = "Fenomena aneh tapi benar-benar normal",
  ui_story_31860101_27_dialog_content = "Beberapa orang bermimpi lebih dari yang lain, tergantung pada kebiasaan tidur mereka.",
  ui_story_31860101_28_dialog_content = "Saya biasanya tidak menolak seluruh mimpi.",
  ui_story_31860101_29_option_content = "Mereka sering memiliki semacam makna khusus",
  ui_story_31860101_30_dialog_content = "Saya pernah mendengar bahwa mimpi terkadang mencerminkan alam bawah sadar Anda, jadi masing-masing memiliki arti yang berbeda.",
  ui_story_31860101_31_dialog_content = "Saya kadang-kadang memimpikan hal-hal yang terjadi di masa lalu, yang saya curigai berhubungan dengan keadaan pikiran saya.",
  ui_story_31860101_32_dialog_content = "Hmm... Sepertinya kamu benar-benar memiliki wawasan tentang mimpimu, PlayerName!",
  ui_story_31860101_33_dialog_content = "Mimpi sebagian besar terjadi selama periode tidur ringan, sedangkan tidur yang lebih dalam biasanya tanpa mimpi.",
  ui_story_31860101_34_dialog_content = "Selama tes dokter, berkat narkolepsi saya—",
  ui_story_31860101_35_dialog_content = "Saya biasanya masuk ke dalam tidur nyenyak cukup cepat.",
  ui_story_31860101_36_dialog_content = "Dengan kata lain, secara alami saya tidak terlalu banyak bermimpi.",
  ui_story_31860101_37_dialog_content = "Oh? Dalam hal ini, impian Anda tidak terjadi begitu saja?",
  ui_story_31860101_38_dialog_content = "Intuisi hakim saya memberi tahu saya bahwa itu tidak sesederhana itu.",
  ui_story_31860101_39_dialog_content = "Jadi saat aku bangun, aku bahkan tidak menyalakan lampu tapi langsung menuju ke ruang bukti—",
  ui_story_31860101_40_dialog_content = "Ada suara-suara yang datang dari dalam, dan beberapa pria mengobrak-abrik!",
  ui_story_31860101_41_dialog_content = "Apa?! Apakah seseorang mencuri file ?!",
  ui_story_31860101_42_dialog_content = "Nah... Seseorang menyelinap di sekitar ruang bukti di tengah malam? Tidak bisa memikirkan hal lain yang bisa terjadi.",
  ui_story_31860101_43_dialog_content = "<color=#e8d9bb>Ruang Bukti, Malam Hari</color>",
  ui_story_31860101_44_dialog_content = "Siapa...",
  ui_story_31860101_45_dialog_content = "A-Argh! Hantu-!",
  ui_story_31860101_46_dialog_content = "Hah? Maksudmu aku?",
  ui_story_31860101_47_dialog_content = "Siapa lagi itu?! Main game di sini...",
  ui_story_31860101_48_dialog_content = "Merayap di sini di tengah malam — siapa kamu!",
  ui_story_31860101_49_dialog_content = "Jangan menghalangi jalanku, atau aku harus menahanmu!",
  ui_story_31860101_50_dialog_content = "Kau akan mengikatku?",
  ui_story_31860101_51_dialog_content = "Bukankah itu hal yang agak vulgar untuk dilakukan pada wanita sepertiku?",
  ui_story_31860101_52_dialog_content = "Vulgar? Tidak heran kau begitu sombong, kau punya bau bangsawan tentangmu.",
  ui_story_31860101_53_dialog_content = "Anda hanya peduli pada keanggunan dan keanggunan dan semua itu ...",
  ui_story_31860101_54_dialog_content = "Huh, aku mencoba memberimu kesempatan untuk bicara.",
  ui_story_31860101_55_dialog_content = "Sepertinya tidak ada apa-apa selain membawamu untuk diinterogasi.",
  ui_story_31860101_56_dialog_content = "Ah!! Apa kekuatan aneh ini?",
  ui_story_31860101_57_dialog_content = "Apa yang Anda katakan tentang menahan? Bagaimana dengan busur kecil... Ya, bagus dan kencang.",
  ui_story_31860101_58_dialog_content = "Tumpahkan. Apa yang kamu lakukan disana?",
  ui_story_31860101_59_dialog_content = "Ugh!",
  ui_story_31860101_60_dialog_content = "Meskipun aku tidak bisa menjamin bagaimana yang lain akan memperlakukanmu besok—",
  ui_story_31860101_61_dialog_content = "Jika Anda jujur kepada saya, saya akan melihat apa yang dapat saya lakukan untuk mengurangi hukuman Anda.",
  ui_story_31860101_62_dialog_content = "Yah, hukuman untuk mimpi burukku!",
  ui_story_31860101_63_dialog_content = "A-Apa?!",
  ui_story_31860101_64_dialog_content = "Jadi, saya sarankan Anda menjawab pertanyaan saya dengan benar — sebelum saya marah.",
  ui_story_31860101_65_dialog_content = "(Aku tidak tahu apa itu, tapi wanita ini memiliki aura yang menakutkan tentang dirinya...)",
  ui_story_31860101_66_dialog_content = "(Mungkin lebih baik mengatakan yang sebenarnya...)",
  ui_story_31860101_67_dialog_content = "Saya hanya pedagang kaki lima biasa dari Lumopolis Bawah. Saya menyamar sebagai penjaga dan menyelinap di siang hari.",
  ui_story_31860101_68_dialog_content = "Dan menunggu sampai sekarang? Tidak heran tidak ada yang memperhatikan. Kami benar-benar perlu meninjau langkah-langkah keamanan kami.",
  ui_story_31860101_69_dialog_content = "Baiklah, Pak Pedagang Kaki Lima Biasa. Apa yang kamu inginkan?",
  ui_story_31860101_70_dialog_content = "Beberapa hari yang lalu, seorang bangsawan menghancurkan kios saya, mengatakan bahwa saya mengotori pakaiannya...",
  ui_story_31860101_71_dialog_content = "Dia menuntut kompensasi yang terlalu tinggi dan mengancam akan menuntut saya jika saya tidak batuk.",
  ui_story_31860101_72_dialog_content = "Itu membunyikan bel, seperti yang terjadi. Saya pikir itu sebenarnya kasus yang akan saya kerjakan nanti.",
  ui_story_31860101_73_dialog_content = "Kamu... Apakah kamu seorang hakim? Di Balai Kehakiman?",
  ui_story_31860101_74_dialog_content = "Oh, aku hanya rekan kecil!",
  ui_story_31860101_75_dialog_content = "Bagaimanapun, kita keluar jalur. Jadi kau datang untuk mencuri berkas kasus untuk menghindari hukuman?",
  ui_story_31860101_76_dialog_content = "I-Itu benar... Aku tidak punya pilihan lain.",
  ui_story_31860101_77_dialog_content = "Bangsawan itu tersandung batu, tetapi menyalahkan kios saya karena menghalangi pandangannya.",
  ui_story_31860101_78_dialog_content = "Dia bahkan mengatakan itu semua karena saya sehingga dia jatuh, tetapi saya hanya berdagang seperti biasa, dan tentu saja tidak menghalangi jalan!",
  ui_story_31860101_79_dialog_content = "File kasus mengklaim bahwa Anda beroperasi secara ilegal, bertentangan dengan peraturan perdagangan Lumopolis.",
  ui_story_31860101_80_dialog_content = "Apakah Anda mengatakan ini tidak benar?",
  ui_story_31860101_81_dialog_content = "Ya, Yang Mulia! Tolong, yang saya minta hanyalah keadilan!",
  ui_story_31860101_82_dialog_content = "Jika benar seperti yang Anda katakan, maka kami perlu membuka kembali penyelidikan.",
  ui_story_31860101_83_dialog_content = "Saya mohon, Yang Mulia!",
  ui_story_31860101_84_dialog_content = "Meski begitu, Anda seharusnya menyikapi hal ini melalui jalur yang tepat.",
  ui_story_31860101_85_dialog_content = "Lagi pula, hilangnya berkas kasus tidak akan mengubah putusan akhir, hanya menunda persidangan.",
  ui_story_31860101_86_dialog_content = "Tapi orang-orang yang datang untuk menyelidiki tidak percaya sepatah kata pun yang saya katakan...",
  ui_story_31860101_87_dialog_content = "Mereka hanya mengira saya sengaja menantang otoritas bangsawan... Apakah Anda sama dengan mereka, dan tidak percaya kepada saya?",
  ui_story_31860101_88_dialog_content = "Tidak tidak. Saya hanya percaya pada fakta yang ditemukan setelah penyelidikan.",
  ui_story_31860101_89_dialog_content = "Seandainya saya tertidur sebentar, saya harus meminta Anda untuk tetap duduk sampai pagi.",
  ui_story_31860101_90_dialog_content = "Kau akan membuatku terikat seperti ini?!",
  ui_story_31860101_91_dialog_content = "Saya sangat menyesal tentang itu... Tapi saya tidak bisa begitu saja membebaskan Anda begitu saja.",
  ui_story_31860101_92_dialog_content = "Anda menghadapi hukuman tambahan untuk masuk tanpa izin dan masuk tanpa izin.",
  ui_story_31860101_93_dialog_content = "Oke, baiklah.",
  ui_story_31860101_94_dialog_content = "Dan itulah yang terjadi.",
  ui_story_31860101_95_dialog_content = "Tidak akan pernah melihat ini datang ...",
  ui_story_31860101_96_dialog_content = "Jadi pria itu yang membangunkanmu?",
  ui_story_31860101_97_dialog_content = "Itu benar. Terkadang saya sulit membedakan mana yang nyata dan mana yang mimpi.",
  ui_story_31860101_98_dialog_content = "Saya tidak sepenuhnya bangun ketika saya pikir saya melihatnya menyelinap, tetapi kemudian saya tertidur lagi.",
  ui_story_31860101_99_dialog_content = "Jadi saya kira itu beruntung Matthieu berteriak padaku!",
  ui_story_31860101_100_dialog_content = "Oh, Tina... Selalu optimis!",
  ui_story_31860101_101_dialog_content = "Lagipula, bagus sekali aku menangkapnya! Setidaknya aku tidak perlu membersihkan Balai Kehakiman selama sebulan penuh.",
  ui_story_31860101_102_dialog_content = "Jadi, apakah semuanya sudah beres?",
  ui_story_31860101_103_dialog_content = "Nah, keesokan harinya, saya melaporkannya kembali ke beberapa Inspektur.",
  ui_story_31860101_104_dialog_content = "Jadi kasus vendor dikembalikan ke tahap pengumpulan bukti, dan saya pribadi pergi ke Lumopolis Bawah untuk penyelidikan.",
  ui_story_31860101_105_dialog_content = "Ternyata dia sepenuhnya patuh, dan tidak ada operasi ilegal.",
  ui_story_31860101_106_dialog_content = "Tunggu, jadi maksudmu pencuri itu mengatakan yang sebenarnya?",
  ui_story_31860101_107_dialog_content = "Benar.",
  ui_story_31860101_108_dialog_content = "Sebagai hakim, saya berharap kasus dapat ditangani secara efisien dan adil.",
  ui_story_31860101_109_dialog_content = "Kejadian ini juga membuat saya mulai memahami, secara lebih pribadi, kehidupan orang-orang di Lumopolis Bawah.",
  ui_story_31860101_110_dialog_content = "Itu bukan hal yang buruk, bukan?",
  ui_story_31860101_111_dialog_content = "Tentu saja tidak! Terkadang, hal-hal yang saya lihat dengan mata saya jauh lebih kuat daripada kata-kata tercetak.",
  ui_story_31860101_112_dialog_content = "Ini tentu saja tidak layak bagi seorang bangsawan untuk menggunakan kekuatan mereka untuk menindas warga sipil.",
  ui_story_31860101_113_dialog_content = "Belakangan, saya membantu vendor membalas kompensasi yang mulia dan menang itu.",
  ui_story_31860101_114_dialog_content = "Namun, putusan tersebut termasuk hukuman untuk mencuri materi, dan hukuman untuk ini dikurangi dari kompensasi.",
  ui_story_31860101_115_dialog_content = "Jadi Hall of Justice adalah pemenang terakhir...",
  ui_story_31860101_116_dialog_content = "Kejadian ini menjadi katalis bagi Balai Kehakiman untuk menata kembali jendela Pamong Praja, sekaligus memperkuat pengamanan.",
  ui_story_31860101_117_dialog_content = "Lagi pula, agak memalukan bagi Balai Kehakiman untuk begitu mudah disusupi oleh warga sipil.",
  ui_story_31860101_118_dialog_content = "Terlepas dari itu, saya mendapat pujian dari Inspektur karena menangkap pencuri itu.",
  ui_story_31860101_119_dialog_content = "Nah, beberapa hal baik muncul dari kerumitan ...",
  ui_story_31860101_120_dialog_content = "Sepertinya narkolepsi tidak selalu hanya masalah!",
  ui_story_31860101_121_dialog_content = "Benar?! Oh, dan PlayerName, Anda tahu saya baru saja bermimpi tentang Colossus?",
  ui_story_31860101_122_dialog_content = "Tidak, apa itu?",
  ui_story_31860101_123_dialog_content = "Hanya setengah sadar, saya pikir saya melihat beberapa bagian dari Colossus hancur berantakan.",
  ui_story_31860101_124_dialog_content = "Mungkinkah ini memiliki arti juga...?",
  ui_story_31860101_125_dialog_content = "Aku juga bertanya-tanya itu...",
  ui_story_31860101_126_dialog_content = "Oh! Beberapa bagian di sini benar-benar rusak! Potongan-potongannya ada di tanah ...",
  ui_story_31860101_127_dialog_content = "... Anda mengatakan kepada saya bahwa seluruh cerita, Tina, apakah karena—",
  ui_story_31860101_128_dialog_content = "—kamu secara tidak sengaja memecahkan sesuatu??",
  ui_story_31860101_129_dialog_content = "Hei, aku tidak bisa mengontrol kekuatan tangan kiriku saat berjalan sambil tidur! Itu karena tidur sambil berjalan, kan?",
  ui_story_31860101_130_dialog_content = "Sepertinya salah satu dari saat-saat itu saya tidak bisa membedakan mimpi dari kenyataan, bukan? Ha ha ha...",
  ui_story_31860101_131_dialog_content = "Tina! Aku bersumpah kau bahkan tidak terkulai kelopak mata, kan?",
  ui_story_31860101_132_dialog_content = "Aku berjanji aku tidur sambil berjalan! Saya sangat menyesal, saya akan membantu Anda memperbaikinya!",
  ui_story_31860601_1_dialog_content = "Sudah lama menunggu, PlayerName?",
  ui_story_31860601_2_dialog_content = "Tina, kamu datang. Aku...",
  ui_story_31860601_3_dialog_content = "Kucing menangkap lidahmu?",
  ui_story_31860601_4_dialog_content = "Oh... maaf. Hanya saja jarang melihatmu berpakaian seperti ini. Ini berbeda.",
  ui_story_31860601_5_dialog_content = "Apakah itu aneh...?",
  ui_story_31860601_6_dialog_content = "Tidak, tidak sama sekali. Itu cocok untukmu.",
  ui_story_31860601_7_dialog_content = "Ini juga benar-benar seperti musim semi.",
  ui_story_31860601_8_dialog_content = "Senang kamu menyukainya.",
  ui_story_31860601_9_dialog_content = "Desainernya cukup sulit. Butuh banyak bujukan untuk membuatnya membuat rok ini untukku.",
  ui_story_31860601_10_dialog_content = "Setelah semua, tidak setiap hari saya bisa piknik dengan kamu dan Toto. Jika itu hanya sama seperti biasanya...",
  ui_story_31860601_11_dialog_content = "Maka itu akan menjadi penghinaan bagi hari yang indah seperti ini.",
  ui_story_31860601_12_dialog_content = "Jadi kamu benar-benar suka piknik, Tina?",
  ui_story_31860601_13_dialog_content = "Kalau begitu, tidak ada waktu untuk disia-siakan. Ayo pergi!",
  ui_story_31860601_14_dialog_content = "<size=30>Bukan piknik yang sebenarnya aku suka...</size>",
  ui_story_31860601_15_dialog_content = "Apa maksudmu, Tina?",
  ui_story_31860601_16_dialog_content = "T-Tidak ada.",
  ui_story_31860601_17_dialog_content = "Ayo pergi. Saya menemukan tempat yang bagus dekat tempat Toto tinggal.",
  ui_story_31860601_18_dialog_content = "Mari kita lihat... Saya rasa Toto belum ada di sini. Kita harus menunggu sebentar.",
  ui_story_31860601_19_dialog_content = "Bagaimanapun, saya tidak pernah tahu ada padang rumput yang begitu indah di sini.",
  ui_story_31860601_20_dialog_content = "Apakah kamu menemukannya, Tina?",
  ui_story_31860601_21_dialog_content = "Saya juga baru mengetahui tentang itu dari surat Toto juga.",
  ui_story_31860601_22_dialog_content = "Saya berpikir saat itu bahwa saya harus menemukan hari yang cerah dan hangat untuk membawa beberapa makanan ringan dan keluar.",
  ui_story_31860601_23_dialog_content = "Duduk di rumput seperti ini. Menikmati kehangatan, merasakan semilir angin, mencium aroma bunga.",
  ui_story_31860601_24_dialog_content = "Dengan Toto yang lucu dalam pandangan saya.",
  ui_story_31860601_25_dialog_content = "Dan memiliki kamu di sampingku.",
  ui_story_31860601_26_dialog_content = "Seperti ini?",
  ui_story_31860601_27_dialog_content = "Hah?",
  ui_story_31860601_28_dialog_content = "PlayerName... Terlalu dekat.",
  ui_story_31860601_29_dialog_content = "Apakah kamu suka seperti ini? Sekarang, kita bisa merasakan kehangatan dan napas satu sama lain.",
  ui_story_31860601_30_dialog_content = "Dan aku bisa memelukmu kapan saja aku mau.",
  ui_story_31860601_31_dialog_content = "A-Apa? Apa yang kamu katakan...?",
  ui_story_31860601_32_dialog_content = "Apa aku bermimpi...?",
  ui_story_31860601_33_dialog_content = "Tidur atau terjaga, aku akan selalu menjagamu.",
  ui_story_31860601_34_dialog_content = "PlayerName…",
  ui_story_31860601_35_dialog_content = "Tina!",
  ui_story_31860601_36_dialog_content = "Oh, Toto. Itu dia.",
  ui_story_31860601_37_dialog_content = "Sudah berabad-abad. Bagaimana kabarmu? Surat lebih baik daripada tidak ada, tapi aku benar-benar merindukanmu...",
  ui_story_31860601_38_dialog_content = "Iya, aku juga!",
  ui_story_31860601_39_dialog_content = "Meskipun memiliki begitu banyak hal yang harus dilakukan hanya untuk bertahan, aku masih merindukanmu setiap hari.",
  ui_story_31860601_40_dialog_content = "Tapi, tidak ada waktu untuk mengejar ketinggalan sekarang!",
  ui_story_31860601_41_dialog_content = "Bangun, Tina!",
  ui_story_31860601_42_dialog_content = "Ada sesuatu yang besar terjadi di luar!",
  ui_story_31860601_43_dialog_content = "Di luar? Bangun? Apakah aku benar-benar...?",
  ui_story_31860601_44_dialog_content = "Argh…",
  ui_story_31860601_45_dialog_content = "Tina! Akhirnya kamu bangun!",
  ui_story_31860601_46_dialog_content = "PlayerName... Hah? Posisi ini... apakah aku masih bermimpi?",
  ui_story_31860601_47_dialog_content = "Bukan hanya itu, tapi kehangatan dan aroma PlayerName... Rasanya benar-benar seperti nyata...",
  ui_story_31860601_48_dialog_content = "<anim type=Shake>Graah!</anim>",
  ui_story_31860601_49_dialog_content = "Heehee, itu mimpi yang bagus.",
  ui_story_31860601_50_dialog_content = "Argh!",
  ui_story_31860601_51_dialog_content = "Kalau saja aku bisa terus bermimpi sedikit lebih lama...",
  ui_story_31860601_52_dialog_content = "Zzz...",
  ui_story_31860601_53_dialog_content = "Tunggu, Tina. Jangan tidur! Lihatlah sekeliling dulu—!",
  ui_story_31860601_54_dialog_content = "Eclipsites ada di mana-mana!",
  ui_story_31860601_55_dialog_content = "<anim type=Shake>Graah!</anim>",
  ui_story_31860601_56_dialog_content = "Hampir saja! Nyaris saja aku terkena!",
  ui_story_31860601_57_dialog_content = "Zzz...",
  ui_story_31860601_58_option_content = "Buat Tina bangun",
  ui_story_31860601_59_dialog_content = "Tina! BANGUN!",
  ui_story_31860601_60_dialog_content = "Kita dalam bahaya!",
  ui_story_31860601_61_option_content = "Pikirkan cara untuk melindungi Tina",
  ui_story_31860601_62_dialog_content = "Saya tidak bisa hanya mengandalkan Tina. Saya perlu melakukan sesuatu.",
  ui_story_31860601_63_dialog_content = "Tapi jika kita terus bersembunyi, cepat atau lambat kita akan tertangkap...",
  ui_story_31860601_64_dialog_content = "Setidaknya bawa Tina ke tempat yang aman!",
  ui_story_31860601_65_dialog_content = "<anim type=Shake>Graah!</anim>",
  ui_story_31860601_66_dialog_content = "Apa, di sini juga?!",
  ui_story_31860601_67_dialog_content = "Ini sudah berakhir. Tak ada tempat untuk sembunyi—!",
  ui_story_31860601_68_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_31860601_69_dialog_content = "Gaah...",
  ui_story_31860601_70_dialog_content = "Oh, betapa aku ingin menikmati mimpi indah ini sedikit lebih lama.",
  ui_story_31860601_71_dialog_content = "Tina!",
  ui_story_31860601_72_dialog_content = "Kamu Eclipsite... Saya mengerti bahwa, sebagai makhluk jahat, kalian tidak pernah diajarkan untuk tidak mengganggu tidur orang.",
  ui_story_31860601_73_dialog_content = "Tapi, ketidaktahuan bukanlah alasan.",
  ui_story_31860601_74_dialog_content = "nafas. Demi White Night di atas, atas nama seorang Judge dari Taman Lumopolis, dengan ini aku menganggapmu bersalah atas kejahatan tercela yang menghalangi cinta.",
  ui_story_31860601_75_dialog_content = "<size=45><color=#FFB400>Beristirahatlah dalam Cahaya Suci!</color></size>",
  ui_story_31860601_76_dialog_content = "Gaah...",
  ui_story_31860601_77_dialog_content = "Tolong, pergi ke kehampaan bersamamu untuk menjalani hukuman abadimu.",
  ui_story_31860601_78_dialog_content = "Itu luar biasa, Tina!",
  ui_story_31860601_79_dialog_content = "Beruntung kamu bangun tepat pada waktunya! Jika tidak, tidak ada yang bisa menebak apa yang mungkin terjadi.",
  ui_story_31860601_80_dialog_content = "Oh, ini tidak sebesar yang kamu buat.",
  ui_story_31860601_81_dialog_content = "Tapi... mengapa Eclipsite dituduh \"menghalangi cinta\"?",
  ui_story_31860601_82_dialog_content = "Yah... kenapa? Haha, saya rasa saya hanya terbiasa mengatakannya di Divisi Percintaan.",
  ui_story_31860601_83_dialog_content = "Oh ya, Toto meninggalkan sesuatu untuk kita di dekat sini dalam mimpiku.",
  ui_story_31860601_84_dialog_content = "Aku akan melihatnya. Dimana mungkin itu berada?",
  ui_story_31860601_85_dialog_content = "... Dalam mimpi? Bagaimana cara kerjanya...?",
  ui_story_31860601_86_dialog_content = "Menemukannya! Di lubang pohon disini.",
  ui_story_31860601_87_dialog_content = "Ini benar-benar nyata?!",
  ui_story_31860601_88_dialog_content = "Ini adalah keranjang dan sebuah surat.",
  ui_story_31860601_89_dialog_content = "\"Sayang Tina...\"",
  ui_story_31860601_90_dialog_content = "Berkat banyaknya Eclipsite yang tiba-tiba muncul di area ini, saya harus meninggalkan tempat tinggal saya saat ini dan mencari tempat lain untuk tinggal.",
  ui_story_31860601_91_dialog_content = "Saya menyesal tidak bisa bergabung denganmu di piknik ini, tapi saya yakin kita akan bertemu lagi.",
  ui_story_31860601_92_dialog_content = "Jadi, jaga dirimu sebelum kita bertemu lagi, Tina, dan hiduplah dengan baik.",
  ui_story_31860601_93_dialog_content = "Jangan seperti sebelumnya, begitu fokus pada barang-barangku hingga kamu mengabaikan orang-orang di sekitarmu.",
  ui_story_31860601_94_dialog_content = "Oh ya! Bukankah patung tanah liat yang kamu tunjukkan padaku sebelumnya dibuat berdasarkan kamu dan kekasihmu?",
  ui_story_31860601_95_dialog_content = "Kamu selalu menjagaku, dan aku ingin melakukan sesuatu untukmu juga! Jadi aku belajar cara membuat kue.",
  ui_story_31860601_96_dialog_content = "Makanlah mereka bersama orang yang kamu cintai.",
  ui_story_31860601_97_dialog_content = "Saya dengar bahwa bagi Aurorian, kue kering dapat mengekspresikan perasaan mereka.",
  ui_story_31860601_98_dialog_content = "Saya harap kue-kue ini dapat membantu Anda menyampaikan perasaan Anda kepada orang yang Anda cintai, Tina.",
  ui_story_31860601_99_dialog_content = "Toto...",
  ui_story_31860601_100_dialog_content = "Keranjang... wow! Ini penuh dengan kue.",
  ui_story_31860601_101_dialog_content = "Apakah Toto membuat ini? Mereka mungkin sedikit bengkok, tapi kamu bisa melihat mereka berbentuk seperti hati.",
  ui_story_31860601_102_dialog_content = "Sepertinya dia telah menghabiskan banyak waktu untuk ini.",
  ui_story_31860601_103_dialog_content = "Ya.",
  ui_story_31860601_104_dialog_content = "Dia menulis dalam surat bahwa dia berharap kita bisa berbagi kue.",
  ui_story_31860601_105_dialog_content = "Jadi, PlayerName, apakah kamu...",
  ui_story_31860601_106_dialog_content = "Maukah kamu menerima gestur ini?",
  ui_story_31860601_107_dialog_content = "Gestur? Ah, tentu saja.",
  ui_story_31860601_108_dialog_content = "Benarkah?!",
  ui_story_31860601_109_dialog_content = "Mengapa saya harus berbohong? Toto bekerja keras untuk memanggang ini.",
  ui_story_31860601_110_dialog_content = "Lalu—",
  ui_story_31860601_111_dialog_content = "Bagaimana mungkin aku bisa menolak kebaikan Toto?",
  ui_story_31860601_112_dialog_content = "...Hah?",
  ui_story_31860601_113_dialog_content = "Jadi, menurutmu kita orang pertama di Astra yang makan kue kering yang dipanggang oleh Eclipsite?",
  ui_story_31860601_114_dialog_content = "Tina? Kenapa kamu tidak makan? Dan kelihatannya kau tidak begitu sehat...",
  ui_story_31860601_115_dialog_content = "Jangan bilang kamu tidak merasa baik karena baru saja dibangunkan?",
  ui_story_31860601_116_dialog_content = "Jangan khawatir. Aku baik-baik saja.",
  ui_story_31860601_117_dialog_content = "Maksud saya, kita tidak bisa menolak gestur Toto...",
  ui_story_31860601_118_dialog_content = "Kamu benar-benar tidak terlihat baik!",
  ui_story_31860601_119_dialog_content = "Beruntung, aku membawa selimut piknik! Ayo istirahat di sini.",
  ui_story_31860601_120_dialog_content = "Aku hanya akan berbaring sebentar.",
  ui_story_31860601_121_dialog_content = "<color=#e8d9bb>Matahari hangat dan angin sejuk menggerakkan dedaunan di pohon-pohon. Suasana masih tenang dan damai.</color>",
  ui_story_31860601_122_dialog_content = "Di sini sangat indah.",
  ui_story_31860601_123_dialog_content = "Sayang sekali kamu sangat menyukai piknik, tapi Eclipsites itu merusak segalanya.",
  ui_story_31860601_124_dialog_content = "Sebenarnya... piknik itu tidak begitu penting.",
  ui_story_31860601_125_dialog_content = "Tapi bukankah kamu sangat menantikannya hingga kamu membuat kostummu sendiri?",
  ui_story_31860601_126_dialog_content = "Itu karena...",
  ui_story_31860601_127_dialog_content = "Ada sebuah puisi yang sangat saya sukai.",
  ui_story_31860601_128_dialog_content = "Puisi?",
  ui_story_31860601_129_dialog_content = "\"Berjalan-jalan di kebun saat musim semi tiba.\"",
  ui_story_31860601_130_dialog_content = "<color=#e8d9bb>Tina menutup matanya di sampingku dan mulai dengan lembut membacakan puisi tersebut.</color>",
  ui_story_31860601_131_dialog_content = "\"Di semak-semak delima.\"",
  ui_story_31860601_132_dialog_content = "\"Ada cahaya, anggur, dan bunga delima.\"",
  ui_story_31860601_133_dialog_content = "Terdengar indah...",
  ui_story_31860601_134_dialog_content = "Zzz...",
  ui_story_31860601_135_dialog_content = "Nah, itu Tina. Tertidur begitu saja.",
  ui_story_31860601_136_dialog_content = "Itu adalah puisi yang sangat indah. Tidak heran kamu sangat suka piknik.",
  ui_story_31860601_137_dialog_content = "Terima kasih... PlayerName...",
  ui_story_31860601_138_dialog_content = "Mengigau?",
  ui_story_31860601_139_dialog_content = "Setidaknya aku memiliki kamu di sini selama empat jam hari ini...",
  ui_story_31860601_140_dialog_content = "Itu sudah cukup untuk dihargai.",
  ui_story_31860601_141_dialog_content = "<color=#e8d9bb>\"Berjalan-jalan di kebun saat musim semi tiba.\"</color>",
  ui_story_31860601_142_dialog_content = "<color=#e8d9bb>\"Di semak-semak delima.\"</color>",
  ui_story_31860601_143_dialog_content = "<color=#e8d9bb>\"Ada cahaya, dan anggur, dan bunga delima.\"</color>",
  ui_story_31860601_144_dialog_content = "<color=#e8d9bb>\"Semua ini tidak berarti tanpa kamu.\"</color>",
  ui_story_31860601_145_dialog_content = "<color=#e8d9bb>\"Dan semua itu akan tidak berarti jika kamu di sini.\"</color>"
}
return config
